// Ensure data directory exists
const dataDir = path.join(__dirname, 'data');
if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir);
}

// Initialize SQLite
const dbPath = path.join(dataDir, 'fuhrpark.db');
const db = new sqlite3.Database(dbPath, (err) => {
  if (err) console.error('Error opening database', err);
  else {
    console.log('Connected to SQLite database at', dbPath);
    // CRITICAL: Enable Foreign Keys to ensure data integrity
    db.run("PRAGMA foreign_keys = ON"); 
  }
});

// Middleware - INCREASED LIMIT FOR FILE UPLOADS
app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ limit: '50mb', extended: true }));

// Serve Favicon
app.get(['/favicon.png', '/favicon.ico'], (req, res) => {
  const faviconPath = path.join(dataDir, 'favicon.png');
  if (fs.existsSync(faviconPath)) {
    res.sendFile(faviconPath);
  } else {
    res.status(404).end();
  }
});

// Helper for Promisified DB
const run = (sql, params = []) => new Promise((resolve, reject) => {
  db.run(sql, params, function (err) {
    if (err) reject(err);
    else resolve(this);
  });
});

const all = (sql, params = []) => new Promise((resolve, reject) => {
  db.all(sql, params, (err, rows) => {
    if (err) reject(err);
    else resolve(rows);
  });
});

const get = (sql, params = []) => new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
});

// Init Tables with Integrity Constraints
