import { useState, useEffect, useCallback } from 'react';
import { Vehicle, LogEntry, Order, OrderStatus, Priority } from '../types';
import { api } from '../api';
import { getTodayDate } from '../utils';

export const useFleetData = () => {
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const loadData = useCallback(async (silentArg: boolean | any = false) => {
        const isSilent = typeof silentArg === 'boolean' ? silentArg : false;

        if (!isSilent) {
            setLoading(true);
            setError(null);
        }

        try {
            const [v, l, o] = await Promise.all([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);

            // Validate data structure before setting state to avoid crashes
            if(Array.isArray(v)) setVehicles(v);
            if(Array.isArray(l)) setLogs(l);
            if(Array.isArray(o)) setOrders(o);

        } catch (e: any) {
            console.error(e);
            if (!isSilent) {
                // Keep old data if possible instead of wiping it, but show error
                setError(e.message || "Fehler beim Laden der Daten");
            }
        } finally {
            if (!isSilent) setLoading(false);
        }
    }, []);

    // Initial Load & Polling
    useEffect(() => { 
        loadData(); 

        const interval = setInterval(() => {
            loadData(true); // Silent update
        }, 30000);

        return () => clearInterval(interval);
    }, [loadData]);

    // --- VEHICLE OPERATIONS ---

    const saveVehicle = async (v: Vehicle) => {
        try {
            if(v.id && vehicles.find(x => x.id === v.id)) {
                await api.put(`/vehicles/${v.id}`, v);
            } else {
                await api.post('/vehicles', v);
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const deleteVehicle = async (id: string) => {
        if(!confirm('Fahrzeug wirklich löschen? Alle zugehörigen Einträge werden ebenfalls gelöscht (Kaskade).')) return false;
        try {
            await api.delete(`/vehicles/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const coupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        const trailer = vehicles.find(v => v.id === trailerId);
        if(motor && trailer) {
            try {
                await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
                await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
                await loadData(true);
            } catch(e) { console.error(e); }
        }
    };

    const uncoupleVehicles = async (motorId: string, trailerId?: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        try {
            if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });

            if(trailerId) {
                const trailer = vehicles.find(v => v.id === trailerId);
                if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
            }
            await loadData(true);
        } catch(e) { console.error(e); }
    };

    // --- LOG / TASK OPERATIONS ---

    const saveLogEntry = async (entries: any[]) => {
        try {
            for (const entry of entries) {
                if(entry.id && logs.find(x => x.id === entry.id)) {
                    await api.put(`/logs/${entry.id}`, entry);
                } else {
                    await api.post('/logs', entry);
                }
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateLogStatus = async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        try {
            await api.put(`/logs/${log.id}`, { ...log, status: newStatus });
            await loadData(true);
        } catch (e) { console.error(e); }
    };

    const deleteLog = async (id: string) => {
        if(!confirm('Eintrag löschen?')) return false;
        try {
            await api.delete(`/logs/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    // --- BUSINESS LOGIC: COMPLETIONS (ATOMIC) ---

    // Completes a generic task and updates vehicle mileage via atomic transaction
    const completeTask = async (log: LogEntry, mileage: number) => {
        try {
            const updatedLog = {
                ...log,
                status: 'DONE',
                dateCompleted: getTodayDate(),
                mileage: mileage
            };

            // Use the transaction endpoint to ensure both happen or neither
            await api.post('/transaction/complete-task', {
                logId: log.id,
                vehicleId: log.vehicleId,
                mileage: mileage,
                logData: updatedLog
            });

            await loadData(true);
            return true;
        } catch(e) { 
            console.error("Atomic transaction failed", e); 
            alert("Fehler beim Speichern. Bitte Verbindung prüfen.");
            return false; 
        }
    };

    // Completes an inspection and calculates next date
    const completeInspection = async (log: LogEntry, nextDate: string) => {
        try {
            const [y, m] = nextDate.split('-'); // YYYY-MM from input

            // 1. Create archival log
            await api.post('/logs', {
                vehicleId: log.vehicleId,
                type: 'Wartung',
                description: `${log.inspectionType} Prüfung durchgeführt`,
                priority: Priority.NORMAL,
                dateAdded: getTodayDate(),
                status: 'DONE',
                dateCompleted: getTodayDate(),
                inspectionType: log.inspectionType
            });

            // 2. Update Vehicle Next Date
            const vehicle = vehicles.find(v => v.id === log.vehicleId);
            if (vehicle && log.inspectionType) {
                // Determine which field to update based on inspection type
                const updateField = `next${log.inspectionType}`; 
                // Store as MM/YYYY
                await api.put(`/vehicles/${vehicle.id}`, { ...vehicle, [updateField]: `${m}/${y}` });
            }

            await loadData(true);
            return true;
        } catch(e) { console.error(e); return false; }
    };

    // --- ORDER OPERATIONS ---

    const saveOrder = async (ordersList: any[]) => {
        try {
            for (const o of ordersList) {
                if(o.id && orders.find(x => x.id === o.id)) {
                    await api.put(`/orders/${o.id}`, o);
                } else {
                    await api.post('/orders', o);
                }
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) {
            await api.put(`/orders/${id}`, { ...order, status });
            await loadData(true);
        }
    };

    const deleteOrder = async (id: string) => {
        if(!confirm('Bestellung löschen?')) return false;
        try {
            await api.delete(`/orders/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    return {
        vehicles, logs, orders, loading, error,
        loadData, saveVehicle, deleteVehicle, coupleVehicles, uncoupleVehicles,
        saveLogEntry, updateLogStatus, deleteLog, completeTask, completeInspection,
        saveOrder, updateOrderStatus, deleteOrder
    };
};

// MockDB for offline fallback
const mockDB = {
    load: (key: string) => {
        try {
            return JSON.parse(localStorage.getItem(`fuhrpark_${key}`) || '[]');
        } catch (e) {
            console.error("MockDB Load Error", e);
            return [];
        }
    },
    save: (key: string, data: any) => localStorage.setItem(`fuhrpark_${key}`, JSON.stringify(data)),

    // Helpers to mimic API delays slightly for realism
    async get(collection: string) {
      return this.load(collection);
    },
    async post(collection: string, item: any) {
      const items = this.load(collection);
      const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
      items.push(newItem);
      this.save(collection, items);
      return { success: true, id: newItem.id };
    },
    async put(collection: string, id: string, item: any) {
      const items = this.load(collection);
      const idx = items.findIndex((i:any) => i.id === id);
      if (idx !== -1) {
        items[idx] = item;
        this.save(collection, items);
      }
      return { success: true };
    },
    async delete(collection: string, id: string) {
      const items = this.load(collection);
      const filtered = items.filter((i:any) => i.id !== id);
      this.save(collection, filtered);
      return { success: true };
    },

    // Simulate the server-side atomic transaction
    async transactionCompleteTask(data: any) {
        const { logId, vehicleId, mileage, logData } = data;

        // 1. Update/Insert Log
        const logs = this.load('logs');
        const existingIdx = logs.findIndex((l:any) => l.id === logId);
        if (existingIdx !== -1) logs[existingIdx] = logData;
        else logs.push(logData);
        this.save('logs', logs);

        // 2. Update Vehicle Mileage (if higher)
        const vehicles = this.load('vehicles');
        const vIdx = vehicles.findIndex((v:any) => v.id === vehicleId);
        if (vIdx !== -1) {
            if (mileage > (vehicles[vIdx].currentMileage || 0)) {
                vehicles[vIdx].currentMileage = mileage;
                this.save('vehicles', vehicles);
            }
        }
        return { success: true };
    }
  };

  let isOfflineMode = false;

  export const getIsOfflineMode = () => isOfflineMode;

  export const api = {
    // Try server first, fallback to mockDB if fails
    request: async (method: string, endpoint: string, data: any = null) => {
      // Special handling for the transaction endpoint
      if (endpoint === '/transaction/complete-task' && isOfflineMode) {
           return mockDB.transactionCompleteTask(data);
      }

      const parts = endpoint.split('/').filter(Boolean);
      const collection = parts[0];
      const id = parts[1];

      if (isOfflineMode) {
         // @ts-ignore
         if (method === 'GET') return mockDB.get(collection);
         // @ts-ignore
         if (method === 'POST') return mockDB.post(collection, data);
         // @ts-ignore
         if (method === 'PUT') return mockDB.put(collection, id, data);
         // @ts-ignore
         if (method === 'DELETE') return mockDB.delete(collection, id);
      }

      try {
        const opts: any = { method, headers: { 'Content-Type': 'application/json' } };
        if (data) opts.body = JSON.stringify(data);

        const res = await fetch(`/api${endpoint}`, opts);
        if (!res.ok) throw new Error('API Error');
        return await res.json();
      } catch (e) {
        if (!isOfflineMode) {
          console.warn('Backend unavailable, switching to Offline Mode (LocalStorage).');
          isOfflineMode = true;
        }
        // Retry with MockDB immediately
        // Handle special transaction route retry manually
        if (endpoint === '/transaction/complete-task') {
            return mockDB.transactionCompleteTask(data);
        }
        return api.request(method, endpoint, data);
      }
    },

    get: (url: string) => api.request('GET', url),
    post: (url: string, data: any) => api.request('POST', url, data),
    put: (url: string, data: any) => api.request('PUT', url, data),
    delete: (url: string) => api.request('DELETE', url)
  };

export enum VehicleType {
  PKW = 'PKW',
  LKW = 'LKW',
  TRANSPORTER = 'Transporter',
  ANHAENGER = 'Anhänger',
  AUFLIEGER = 'Auflieger',
  SONSTIGE = 'Sonstige',
  MASCHINE = 'Maschine'
}

export enum Priority {
  LOW = 'Niedrig',
  NORMAL = 'Normal',
  HIGH = 'Dringend',
}

export enum OrderStatus {
  OFFEN = 'Offen',
  BESTELLT = 'Bestellt',
  ERLEDIGT = 'Erledigt',
}

export interface Attachment {
  name: string;
  data: string; // Base64
  type: string;
}

export interface Vehicle {
  id: string;
  licensePlate: string;
  type: VehicleType | string;
  manufacturer: string;
  model: string; // Typ
  vin: string;
  year: number;
  notes: string;
  coupledVehicleId?: string | null; // For LKW <-> Auflieger

  // Inspection Due Dates (MM/YYYY)
  nextHU?: string;
  nextSP?: string;
  nextUVV?: string;
  nextTacho?: string;

  currentMileage?: number; // KM or Hours
  registrationDoc?: string; // Base64 PDF Data
}

export interface LogEntry {
  id: string;
  vehicleId: string;
  type: string; // Generic 'Aufgabe'
  description: string;
  priority: Priority;
  dateAdded: string; // ISO Date
  dateCompleted?: string;
  status: 'OPEN' | 'IN_PROGRESS' | 'DONE';
  mileage?: number;

  // Specific for inspections
  inspectionType?: 'HU' | 'SP' | 'UVV' | 'Tacho';

  // Attachments
  attachments?: Attachment[];

  // Frontend specific
  isVirtual?: boolean; // If true, this is a generated inspection task, not saved in DB yet
}

export interface Order {
  id: string;
  description: string;
  vehicleId?: string;
  dateAdded: string;
  status: OrderStatus;
  supplier?: string;
}

