// Helper for Promisified DB
const run = (sql, params = []) => new Promise((resolve, reject) => {
  db.run(sql, params, function (err) {
    if (err) reject(err);
    else resolve(this);
  });
});

const all = (sql, params = []) => new Promise((resolve, reject) => {
  db.all(sql, params, (err, rows) => {
    if (err) reject(err);
    else resolve(rows);
  });
});

const get = (sql, params = []) => new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
});

// Init Tables with Integrity Constraints
db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS vehicles (
    id TEXT PRIMARY KEY, 
    licensePlate TEXT, 
    type TEXT, 
    manufacturer TEXT, 
    model TEXT, 
    vin TEXT, 
    year INTEGER, 
    notes TEXT, 
    coupledVehicleId TEXT, 
    nextHU TEXT, 
    nextSP TEXT, 
    nextUVV TEXT, 
    nextTacho TEXT, 
    currentMileage INTEGER,
    registrationDoc TEXT
  )`);

  // Migration for existing tables
  db.run("ALTER TABLE vehicles ADD COLUMN registrationDoc TEXT", (err) => {});

  db.run(`CREATE TABLE IF NOT EXISTS logs (
    id TEXT PRIMARY KEY, 
    vehicleId TEXT, 
    type TEXT, 
    description TEXT, 
    priority TEXT, 
    dateAdded TEXT, 
    dateCompleted TEXT, 
    status TEXT, 
    mileage INTEGER, 
    inspectionType TEXT, 
    attachments TEXT,
    FOREIGN KEY(vehicleId) REFERENCES vehicles(id) ON DELETE CASCADE
  )`);

  db.run("ALTER TABLE logs ADD COLUMN attachments TEXT", (err) => {});

  db.run(`CREATE TABLE IF NOT EXISTS orders (
    id TEXT PRIMARY KEY, 
    description TEXT, 
    vehicleId TEXT, 
    dateAdded TEXT, 
    status TEXT, 
    supplier TEXT
  )`);
  db.run("ALTER TABLE orders ADD COLUMN supplier TEXT", (err) => {});

