// Atomic Task Completion: Updates Log AND Vehicle Mileage in one transaction
app.post('/api/transaction/complete-task', async (req, res) => {
    const { logId, vehicleId, mileage, logData } = req.body;

    db.serialize(() => {
        db.run("BEGIN TRANSACTION");

        const attachmentsJson = JSON.stringify(logData.attachments || []);

        // 1. Update Log
        db.run(`INSERT OR REPLACE INTO logs VALUES (?,?,?,?,?,?,?,?,?,?,?)`, 
            [logId, logData.vehicleId, logData.type, logData.description, logData.priority || 'Normal', logData.dateAdded, logData.dateCompleted, 'DONE', mileage, logData.inspectionType, attachmentsJson], 
            function(err) {
                if (err) {
                    console.error("Trans Error Log:", err);
                    db.run("ROLLBACK");
                    return res.status(500).json({ error: err.message });
                }

                // 2. Check and Update Vehicle Mileage (only if higher)
                db.get("SELECT currentMileage FROM vehicles WHERE id = ?", [vehicleId], (err, row) => {
                    if (err) {
                        db.run("ROLLBACK");
                        return res.status(500).json({ error: err.message });
                    }

                    if (row && mileage > (row.currentMileage || 0)) {
                         db.run("UPDATE vehicles SET currentMileage = ? WHERE id = ?", [mileage, vehicleId], function(err) {
                            if (err) {
                                db.run("ROLLBACK");
                                return res.status(500).json({ error: err.message });
                            }
                            db.run("COMMIT");
                            res.json({ success: true });
                         });
                    } else {
                        // No mileage update needed, just commit
                        db.run("COMMIT");
                        res.json({ success: true });
                    }
                });
            }
        );
    });
});

