import { Icons } from '../icons';
import { getTodayDate, toInputFormat, fromInputFormat, getVehicleTypePriority, groupVehiclesByType } from '../utils';

// --- HELPER ---
const PriorityCheckbox = ({ label, checked, onChange }: any) => (
    <label className="flex items-center gap-1 cursor-pointer select-none text-sm">
        <input 
            type="checkbox" 
            checked={checked} 
            onChange={onChange}
            className="w-4 h-4 accent-blue-600"
        />
        {label}
    </label>
);

