                    </div>

                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-1">Notizen</label>
                        <textarea 
                            className="w-full border border-gray-300 p-2 rounded h-20 focus:ring-2 focus:ring-blue-500 outline-none resize-none" 
