        notes: '',
        currentMileage: 0,
        registrationDoc: '',
        ...vehicle
    });

    // CRITICAL FIX: Only update form data when Modal OPENS or ID changes. 
    // Do NOT add 'vehicle' to dependency array to prevent overwriting user input on background polling updates.
    useEffect(() => { 
