import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Vehicle, LogEntry, Order, Priority } from './types';
import { getTodayDate } from './utils';

// Context & Provider
import { FleetProvider, useFleet } from './context/FleetContext';

// Components
import { ErrorBoundary } from './components/Common';
import { Layout } from './components/Layout';
import { VehicleModal, EntryModal, OrderModal, InspectionModal, CompletionModal } from './components/Modals';

// Views
import { DashboardView } from './views/DashboardView';
import { VehicleListView, CombinationsView } from './views/VehicleView';
import { AppointmentsView, OrdersView } from './views/PlanningView';
import { HistoryView, AdminView } from './views/ReportView';
import { AnalysisView } from './views/AnalysisView';

// The Inner App handles UI State (Modals, Routing) but consumes Data from Context
const FleetApp = () => {
    const [view, setView] = useState('dashboard');

    // Access Data & Actions via Context
    const { 
        loading, loadData, vehicles,
        saveVehicle, saveLogEntry, saveOrder, 
        updateLogStatus, completeTask, completeInspection 
    } = useFleet();

    // Modal UI States
    const [vehicleModal, setVehicleModal] = useState({ open: false, data: null as Vehicle | null });
    const [entryModal, setEntryModal] = useState({ open: false, data: null as LogEntry | null });
    const [orderModal, setOrderModal] = useState({ open: false, data: null as Order | null });
    const [inspectionModal, setInspectionModal] = useState({ open: false, data: null as LogEntry | null });
    const [completionModal, setCompletionModal] = useState({ open: false, data: null as LogEntry | null });

    // Handlers that bridge UI to Data Actions
    const handleStatusUpdate = (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        if (newStatus === 'DONE') {
            setCompletionModal({ open: true, data: log });
        } else {
            updateLogStatus(log, newStatus);
        }
    };

    const handleInspectionCompletion = async (log: LogEntry, nextDate: string) => {
        const success = await completeInspection(log, nextDate);
        if (success) setInspectionModal({ open: false, data: null });
    };

    const handleTaskCompletion = async (log: LogEntry, mileage: number) => {
        const success = await completeTask(log, mileage);
        if (success) setCompletionModal({ open: false, data: null });
    };

    const handleSaveVehicle = async (v: Vehicle) => {
        const success = await saveVehicle(v);
        if (success) setVehicleModal({ open: false, data: null });
    };

    const handleSaveEntry = async (entries: any[]) => {
        const success = await saveLogEntry(entries);
        if (success) setEntryModal({ open: false, data: null });
    };

    const handleSaveOrder = async (ordersList: any[]) => {
        const success = await saveOrder(ordersList);
        if (success) setOrderModal({ open: false, data: null });
    };

    // Virtual Inspection Helper for View Logic
    const openVirtualInspection = (apt: any) => {
        setInspectionModal({ 
            open: true, 
            data: { 
                id: `virt_${apt.vid}_${apt.inspectionType}`, 
                vehicleId: apt.vid, 
                type: 'Prüfung', 
                description: `${apt.inspectionType} Fällig (${apt.date})`, 
                priority: Priority.NORMAL, 
                dateAdded: getTodayDate(), 
                status: 'OPEN', 
                inspectionType: apt.inspectionType, 
                isVirtual: true 
            } as LogEntry 
        });
    };

    return (
        <Layout currentView={view} setView={setView} onRefresh={loadData}>
            <ErrorBoundary>
                {loading ? <div className="flex justify-center items-center h-full text-gray-400">Laden...</div> : (
                    <>
                        {view === 'dashboard' && (
                            <DashboardView 
                                onAdd={() => setEntryModal({open:true, data:null})} 
                                onInspect={(l:any) => setInspectionModal({open: true, data: l})} 
                                onStatusUpdate={handleStatusUpdate} 
                                onEdit={(l:any) => setEntryModal({open:true, data:l})} 
                            />
                        )}
                        {view === 'vehicles' && (
                            <VehicleListView 
                                onAdd={() => setVehicleModal({open:true, data:null})} 
                                onEdit={(v:any) => setVehicleModal({open:true, data:v})} 
                            />
                        )}
                        {view === 'combinations' && <CombinationsView />}
                        {view === 'appointments' && (
                            <AppointmentsView onComplete={openVirtualInspection} />
                        )}
                        {view === 'orders' && (
                            <OrdersView 
                                onAdd={() => setOrderModal({open:true, data:null})} 
                                onEdit={(o:any) => setOrderModal({open:true, data:o})} 
                            />
                        )}
                        {view === 'history' && (
                            <HistoryView onEdit={(l:any) => setEntryModal({open:true, data:l})} />
                        )}
                        {view === 'analysis' && <AnalysisView />}
                        {view === 'admin' && <AdminView />}
                    </>
                )}
            </ErrorBoundary>

            {/* Global Modals */}
            <VehicleModal 
                isOpen={vehicleModal.open} 
                onClose={() => setVehicleModal({open:false, data:null})} 
                vehicle={vehicleModal.data} 
                onSave={handleSaveVehicle} 
            />
            <EntryModal 
                isOpen={entryModal.open} 
                onClose={() => setEntryModal({open:false, data:null})} 
                entry={entryModal.data} 
                vehicles={vehicles} 
                onSave={handleSaveEntry} 
            />
            <OrderModal 
                isOpen={orderModal.open} 
                onClose={() => setOrderModal({open:false, data:null})} 
                order={orderModal.data} 
                vehicles={vehicles} 
                onSave={handleSaveOrder} 
            />
            <InspectionModal 
                isOpen={inspectionModal.open} 
                onClose={() => setInspectionModal({open:false, data:null})} 
                log={inspectionModal.data} 
                onSave={handleInspectionCompletion} 
            />
            <CompletionModal 
                isOpen={completionModal.open} 
                onClose={() => setCompletionModal({open:false, data:null})} 
                log={completionModal.data} 
                onConfirm={handleTaskCompletion} 
            />
        </Layout>
    );
};

const App = () => (
    <FleetProvider>
        <FleetApp />
    </FleetProvider>
);

const container = document.getElementById('root');
const root = createRoot(container!);
root.render(<App />);

import React, { useState, useMemo } from 'react';
import { Vehicle, LogEntry, VehicleType, Priority } from '../types';
import { Icons } from '../icons';
import { getVehicleTypePriority, getPrioritySortValue, generateVirtualInspections } from '../utils';
import { useFleet } from '../context/FleetContext';

export const DashboardView = ({ onStatusUpdate, onEdit, onAdd, onInspect }: any) => {
  // Consume Data from Context
  const { logs, vehicles, deleteLog } = useFleet();

  const safeVehicles = Array.isArray(vehicles) ? vehicles : [];
  const [showCompleted, setShowCompleted] = useState(false);
  const [sortMode, setSortMode] = useState<'priority' | 'type' | 'license'>('priority');
  const [filters, setFilters] = useState({ licensePlate: '', type: '', priority: '', category: '' });

  const generatedInspections: LogEntry[] = useMemo(() => generateVirtualInspections(safeVehicles), [safeVehicles]);

  const filteredLogs = useMemo(() => {
    const allItems = [...logs, ...generatedInspections];
    return allItems.filter((l: LogEntry) => {
        if (!showCompleted && l.status === 'DONE') return false;
        const vehicle = safeVehicles.find((v:Vehicle) => v.id === l.vehicleId);
        const licensePlate = vehicle?.licensePlate || 'Allgemein';
        const type = vehicle?.type || 'Sonstige';

        if (filters.licensePlate && !licensePlate.toLowerCase().includes(filters.licensePlate.toLowerCase())) return false;
        if (filters.type && type !== filters.type) return false;
        if (filters.priority && l.priority !== filters.priority) return false;
        if (filters.category === 'inspection' && (!l.inspectionType && l.type !== 'Wartung' && l.type !== 'Prüfung')) return false;
        if (filters.category === 'task' && (l.inspectionType || l.type === 'Wartung' || l.type === 'Prüfung')) return false;
        return true;
    });
  }, [logs, generatedInspections, safeVehicles, showCompleted, filters]);

  const groupedLogs = useMemo(() => {
      const groups: { [key: string]: LogEntry[] } = {};
      filteredLogs.forEach((log: LogEntry) => {
          const key = log.vehicleId || 'unknown';
          if (!groups[key]) groups[key] = [];
          groups[key].push(log);
      });
      Object.keys(groups).forEach(key => {
          groups[key].sort((a, b) => {
              const statusOrder = { 'IN_PROGRESS': 0, 'OPEN': 1, 'DONE': 2 };
              if (a.status !== b.status) return statusOrder[a.status] - statusOrder[b.status];
              const pA = getPrioritySortValue(a.priority);
              const pB = getPrioritySortValue(b.priority);
              if (pA !== pB) return pA - pB;
              return a.dateAdded.localeCompare(b.dateAdded);
          });
      });
      return groups;
  }, [filteredLogs]);

  const sortedGroupKeys = useMemo(() => {
      const keys = Object.keys(groupedLogs);
      return keys.sort((a, b) => {
         const vA = safeVehicles.find((v:Vehicle) => v.id === a);
         const vB = safeVehicles.find((v:Vehicle) => v.id === b);
         if (sortMode === 'priority') {
             const minPrio = (tasks: LogEntry[]) => tasks.length === 0 ? 99 : Math.min(...tasks.map(t => getPrioritySortValue(t.priority)));
             const pA = minPrio(groupedLogs[a]), pB = minPrio(groupedLogs[b]);
             if (pA !== pB) return pA - pB;
             return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
         } else if (sortMode === 'type') {
             const pA = getVehicleTypePriority(vA?.type || 'Sonstige'), pB = getVehicleTypePriority(vB?.type || 'Sonstige');
             if (pA !== pB) return pA - pB;
             return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
         } else {
             return (vA?.licensePlate || 'ZZ').localeCompare(vB?.licensePlate || 'ZZ');
         }
      });
  }, [groupedLogs, safeVehicles, sortMode]);

  return (
    <div className="space-y-4">
      <div className="bg-white p-3 rounded shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-3">
          <div className="flex items-center gap-4 flex-wrap">
              <h2 className="text-xl font-bold text-gray-800 whitespace-nowrap">Aufgaben</h2>
              <div className="h-6 w-px bg-gray-300 hidden md:block"></div>
              <div className="flex items-center gap-2">
                 <div className="relative group">
                      <span className="absolute left-2.5 top-2 text-gray-400 pointer-events-none"><Icons.SortAsc /></span>
                       <select className="w-36 py-1.5 pl-8 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-700 appearance-none cursor-pointer font-bold" value={sortMode} onChange={e => setSortMode(e.target.value as any)}>
                          <option value="priority">Priorität</option>
                          <option value="type">Fahrzeugtyp</option>
                          <option value="license">Kennzeichen</option>
                      </select>
                 </div>
              </div>
              <div className="h-6 w-px bg-gray-300 hidden md:block"></div>
              <div className="flex flex-wrap items-center gap-2">
                  <div className="relative group">
                      <span className="absolute left-2.5 top-2 text-gray-400 group-focus-within:text-blue-500 pointer-events-none"><Icons.Search /></span>
                      <input type="text" placeholder="Suchen..." className="w-32 md:w-48 pl-8 pr-2 py-1.5 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none" value={filters.licensePlate} onChange={e => setFilters({...filters, licensePlate: e.target.value})} />
                  </div>
                  <div className="relative">
                       <select className="w-28 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer" value={filters.type} onChange={e => setFilters({...filters, type: e.target.value})}>
                          <option value="">Alle Arten</option>
                          {Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                  </div>
                   <div className="relative">
                       <select className="w-28 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer" value={filters.priority} onChange={e => setFilters({...filters, priority: e.target.value})}>
                          <option value="">Alle Prio</option>
                          {Object.values(Priority).map(p => <option key={p} value={p}>{p}</option>)}
                      </select>
                  </div>
                   <div className="relative">
                       <select className="w-32 py-1.5 pl-2 pr-6 text-sm border border-gray-300 rounded focus:border-blue-500 outline-none bg-white text-gray-600 appearance-none cursor-pointer" value={filters.category} onChange={e => setFilters({...filters, category: e.target.value})}>
                          <option value="">Alle Einträge</option>
                          <option value="inspection">Nur Prüfungen</option>
                          <option value="task">Nur Aufgaben</option>
                      </select>
                  </div>
                  {(filters.licensePlate || filters.type || filters.priority || filters.category) && (
                      <button onClick={() => setFilters({licensePlate: '', type: '', priority: '', category: ''})} className="text-gray-400 hover:text-red-500 p-1.5 rounded hover:bg-red-50" title="Filter löschen"><Icons.Trash /></button>
                  )}
              </div>
          </div>
          <div className="flex items-center gap-2 shrink-0 self-end md:self-auto">
               <button onClick={() => setShowCompleted(!showCompleted)} className={`p-2 rounded border transition-colors ${showCompleted ? 'bg-blue-50 text-blue-600 border-blue-200' : 'bg-white text-gray-400 border-gray-200 hover:border-gray-300'}`}>{showCompleted ? <Icons.Eye /> : <Icons.EyeOff />}</button>
               <button onClick={onAdd} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded flex items-center gap-2 shadow-sm font-bold text-sm"><Icons.Plus /> Neu</button>
          </div>
      </div>

      <div className="flex flex-col gap-4">
        {sortedGroupKeys.length === 0 && <div className="col-span-full text-center py-12 text-gray-400 bg-gray-50 rounded border border-dashed border-gray-300">Keine Aufgaben gefunden.</div>}
        {sortedGroupKeys.map((vid, index) => {
          const vehicleLogs = groupedLogs[vid];
          const vehicle = safeVehicles.find((v:Vehicle) => v.id === vid);
          const coupledVehicle = vehicle?.coupledVehicleId ? safeVehicles.find((v:Vehicle) => v.id === vehicle.coupledVehicleId) : null;
          const hasUrgent = vehicleLogs.some(l => l.priority === Priority.HIGH);
          const currentType = vehicle?.type || 'Sonstige';
          const prevVid = sortedGroupKeys[index - 1];
          const prevVehicle = safeVehicles.find((v:Vehicle) => v.id === prevVid);
          const prevType = prevVehicle?.type || 'Sonstige';
          const showGroupHeader = sortMode === 'type' && (index === 0 || currentType !== prevType);

          return (
            <React.Fragment key={vid}>
                {showGroupHeader && (
                    <div className="mt-4 first:mt-0 flex items-center gap-3">
                         <div className="text-gray-500 font-bold uppercase text-xs tracking-wider bg-gray-100 px-3 py-1 rounded-full border border-gray-200">{currentType}</div>
                         <div className="h-px bg-gray-300 flex-1 opacity-50"></div>
                    </div>
                )}
                <div className="bg-white rounded shadow-sm border border-gray-200 overflow-hidden flex flex-col w-full">
                <div className="bg-slate-50 border-b border-gray-200 px-3 py-2 flex justify-between items-center">
                    <div>
                        <div className="font-bold text-base text-slate-800 flex items-center gap-2">
                            {vehicle ? vehicle.licensePlate : 'Allgemein / Lager'}
                            {coupledVehicle && (
                                <span className="text-xs text-gray-400 font-normal flex items-center gap-1 ml-2" title={`Gekoppelt mit: ${coupledVehicle.licensePlate}`}>
                                    <span className="opacity-50 scale-75"><Icons.Link /></span> {coupledVehicle.licensePlate}
                                </span>
                            )}
                        </div>
                        {vehicle && <div className="text-[10px] text-slate-500">{vehicle.manufacturer} {vehicle.model} • {vehicle.type}</div>}
                    </div>
                    <div className={`${hasUrgent ? 'bg-red-100 text-red-700 border border-red-200' : 'bg-slate-200 text-slate-600'} px-2 py-0.5 rounded-full text-[10px] font-bold`}>{vehicleLogs.length}</div>
                </div>
                <div className="divide-y divide-gray-100">
                    {vehicleLogs.map((log: LogEntry) => {
                        const isDone = log.status === 'DONE';
                        const isInProgress = log.status === 'IN_PROGRESS';
                        return (
                            <div key={log.id} className={`p-2 group transition-colors ${isInProgress ? 'bg-amber-50' : isDone ? 'bg-gray-50 opacity-75' : 'hover:bg-blue-50'}`}>
                                <div className="flex justify-between items-start gap-1.5">
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-0.5">
                                                <span className={`px-1.5 py-0.5 rounded-[3px] text-[10px] font-bold uppercase tracking-wider border ${log.priority === Priority.HIGH ? 'bg-red-100 text-red-800 border-red-200' : log.priority === Priority.LOW ? 'bg-gray-100 text-gray-600 border-gray-200' : 'bg-blue-50 text-blue-800 border-blue-100'}`}>{log.priority}</span>
                                                {isInProgress && <span className="text-[10px] font-bold text-amber-600 flex items-center gap-1 bg-amber-100 px-1.5 py-0.5 rounded border border-amber-200"><Icons.Clock /> In Bearbeitung</span>}
                                                {log.isVirtual && <span className="text-[10px] font-bold text-purple-600 bg-purple-100 px-1.5 py-0.5 rounded border border-purple-200 ml-1">PRÜFUNG</span>}
                                        </div>
                                        <div className={`text-sm text-gray-800 whitespace-pre-wrap ${isDone ? 'line-through text-gray-500' : ''}`}>{log.description}</div>
                                        <div className="text-[10px] text-gray-400 mt-0.5 flex gap-2"><span>Erstellt: {log.dateAdded}</span>{log.mileage && <span>• KM: {log.mileage}</span>}</div>
                                    </div>
                                    <div className="flex flex-col gap-1 items-end">
                                        {!isDone && (
                                            <div className="flex gap-1">
                                                {!isInProgress && !log.isVirtual && (
                                                    <button onClick={() => onStatusUpdate(log, 'IN_PROGRESS')} className="p-1 bg-white border border-gray-200 text-amber-500 hover:bg-amber-50 hover:border-amber-300 rounded shadow-sm transition-all" title="In Bearbeitung setzen"><Icons.Clock /></button>
                                                )}
                                                <button onClick={() => log.isVirtual ? onInspect(log) : onStatusUpdate(log, 'DONE')} className="p-1 bg-white border border-gray-200 text-green-600 hover:bg-green-50 hover:border-green-300 rounded shadow-sm transition-all" title={log.isVirtual ? "Prüfung durchführen" : "Erledigen"}><Icons.Check /></button>
                                            </div>
                                        )}
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            {!log.isVirtual && (
                                                <>
                                                <button onClick={() => onEdit(log)} className="p-1 text-blue-400 hover:text-blue-600"><Icons.Edit /></button>
                                                <button onClick={() => deleteLog(log.id)} className="p-1 text-red-300 hover:text-red-600"><Icons.Trash /></button>
                                                </>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
                </div>
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Vehicle, VehicleType } from '../types';
import { Icons } from '../icons';
import { getVehicleTypePriority, parseDateMMYYYY } from '../utils';
import { DateCell } from '../components/Common';
import { useFleet } from '../context/FleetContext';

export const VehicleListView = ({ onEdit, onAdd }: any) => {
  const { vehicles, deleteVehicle } = useFleet();

  const [sortConfig, setSortConfig] = useState<{ key: string | null, direction: 'asc' | 'desc' }>({ key: null, direction: 'asc' });
  const [filters, setFilters] = useState<{ [key: string]: string }>({});
  const [selectedVehicleForDoc, setSelectedVehicleForDoc] = useState<Vehicle | null>(null);

  const handleSort = (key: keyof Vehicle | 'modelFull') => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const handleFilterChange = (key: string, value: string) => setFilters(prev => ({ ...prev, [key]: value }));

  const processedVehicles = useMemo(() => {
    if (!vehicles || !Array.isArray(vehicles)) return [];
    let filtered = [...vehicles];
    Object.keys(filters).forEach(key => {
        const filterVal = filters[key].toLowerCase();
        if(!filterVal) return;
        filtered = filtered.filter(v => {
            let valToCheck = '';
            if (key === 'modelFull') valToCheck = `${v.manufacturer || ''} ${v.model || ''}`;
            // @ts-ignore
            else if (v[key]) valToCheck = String(v[key]);
            return valToCheck.toLowerCase().includes(filterVal);
        });
    });
    if (sortConfig.key) {
        filtered.sort((a, b) => {
            let valA: any = sortConfig.key === 'modelFull' ? `${a.manufacturer || ''} ${a.model || ''}` : a[sortConfig.key as keyof Vehicle];
            let valB: any = sortConfig.key === 'modelFull' ? `${b.manufacturer || ''} ${b.model || ''}` : b[sortConfig.key as keyof Vehicle];
            if (valA === undefined || valA === null) valA = '';
            if (valB === undefined || valB === null) valB = '';
            if (sortConfig.key === 'year') {
                const numA = Number(valA) || 0; const numB = Number(valB) || 0;
                return sortConfig.direction === 'asc' ? (numA - numB) : (numB - numA);
            }
            if (['nextHU', 'nextSP', 'nextUVV', 'nextTacho'].includes(sortConfig.key as string)) {
                const dateA = parseDateMMYYYY(String(valA)); const dateB = parseDateMMYYYY(String(valB));
                return sortConfig.direction === 'asc' ? (dateA - dateB) : (dateB - dateA);
            }
            if (sortConfig.key === 'type') {
                const pA = getVehicleTypePriority(valA); const pB = getVehicleTypePriority(valB);
                return sortConfig.direction === 'asc' ? (pA - pB) : (pB - pA);
            }
            return sortConfig.direction === 'asc' ? String(valA).localeCompare(String(valB)) : String(valB).localeCompare(String(valA));
        });
    }
    return filtered;
  }, [vehicles, sortConfig, filters]);

  const getSortIcon = (colKey: string) => {
     if (sortConfig.key !== colKey) return <span className="text-gray-300"><Icons.SortDefault /></span>;
     return sortConfig.direction === 'asc' ? <span className="text-blue-600"><Icons.SortAsc /></span> : <span className="text-blue-600"><Icons.SortDesc /></span>;
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Fahrzeuge</h2>
        <div className="flex gap-2">
          <button onClick={onAdd} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2"><Icons.Plus /> Neu</button>
        </div>
      </div>
      <div className="bg-white rounded shadow overflow-x-auto border border-gray-200">
        <table className="w-full text-left border-collapse min-w-[1000px]">
          <thead className="bg-gray-50 text-gray-600 text-sm uppercase tracking-wider">
            <tr className="border-b border-gray-200">
              <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('licensePlate')}><div className="flex items-center gap-2">Kennzeichen {getSortIcon('licensePlate')}</div></th>
              <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('type')}><div className="flex items-center gap-2">Typ {getSortIcon('type')}</div></th>
              <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('modelFull')}><div className="flex items-center gap-2">Fahrzeug {getSortIcon('modelFull')}</div></th>
               <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('year')}><div className="flex items-center gap-2">Baujahr {getSortIcon('year')}</div></th>
               <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('vin')}><div className="flex items-center gap-2">FIN {getSortIcon('vin')}</div></th>
              <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('nextHU')}><div className="flex items-center gap-2">HU {getSortIcon('nextHU')}</div></th>
               <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('nextSP')}><div className="flex items-center gap-2">SP {getSortIcon('nextSP')}</div></th>
               <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('nextUVV')}><div className="flex items-center gap-2">UVV {getSortIcon('nextUVV')}</div></th>
               <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('nextTacho')}><div className="flex items-center gap-2">Tacho {getSortIcon('nextTacho')}</div></th>
              <th className="p-3 w-24">Aktionen</th>
            </tr>
            <tr className="bg-gray-50 border-b border-gray-300">
                <th className="p-2"><input className="w-full text-xs border border-gray-300 rounded px-2 py-1 outline-none" placeholder="Filter..." value={filters.licensePlate || ''} onChange={e => handleFilterChange('licensePlate', e.target.value)} /></th>
                <th className="p-2"><select className="w-full text-xs border border-gray-300 rounded px-2 py-1 outline-none bg-white" value={filters.type || ''} onChange={e => handleFilterChange('type', e.target.value)}><option value="">Alle</option>{Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}</select></th>
                <th className="p-2"><input className="w-full text-xs border border-gray-300 rounded px-2 py-1 outline-none" placeholder="Modell..." value={filters.modelFull || ''} onChange={e => handleFilterChange('modelFull', e.target.value)} /></th>
                <th className="p-2"><input className="w-full text-xs border border-gray-300 rounded px-2 py-1 outline-none" placeholder="Jahr" value={filters.year || ''} onChange={e => handleFilterChange('year', e.target.value)} /></th>
                 <th className="p-2"><input className="w-full text-xs border border-gray-300 rounded px-2 py-1 outline-none" placeholder="FIN" value={filters.vin || ''} onChange={e => handleFilterChange('vin', e.target.value)} /></th>
                <th className="p-2" colSpan={5}></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {processedVehicles.length === 0 && <tr><td colSpan={10} className="p-8 text-center text-gray-500 italic">Keine Fahrzeuge gefunden.</td></tr>}
            {processedVehicles.map((v: Vehicle) => (
              <tr key={v.id} className="hover:bg-blue-50 transition-colors">
                <td className="p-3 font-bold text-gray-800">{v.licensePlate}</td>
                <td className="p-3"><span className="px-2 py-0.5 rounded-full bg-gray-100 text-gray-600 text-xs font-bold border border-gray-200">{v.type}</span></td>
                <td className="p-3 text-gray-700 text-sm">{v.manufacturer} {v.model}</td>
                <td className="p-3 text-gray-700 text-sm">{v.year}</td>
                <td className="p-3 text-gray-500 font-mono text-xs">{v.vin}</td>
                <td className="p-3 text-sm"><DateCell date={v.nextHU} /></td>
                <td className="p-3 text-sm"><DateCell date={v.nextSP} /></td>
                <td className="p-3 text-sm"><DateCell date={v.nextUVV} /></td>
                <td className="p-3 text-sm"><DateCell date={v.nextTacho} /></td>
                <td className="p-3 flex gap-2">
                  <button onClick={() => onEdit(v)} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded" title="Bearbeiten"><Icons.Edit /></button>
                  {v.registrationDoc && (
                      <button 
                        onClick={() => setSelectedVehicleForDoc(selectedVehicleForDoc?.id === v.id ? null : v)} 
                        className={`p-1.5 rounded ${selectedVehicleForDoc?.id === v.id ? 'bg-blue-600 text-white' : 'text-gray-500 hover:bg-gray-100'}`}
                        title="Fahrzeugschein anzeigen"
                      >
