 </div>
);

const StatusButton = ({ currentStatus, targetStatus, icon, colorClass, onClick, label }: any) => (
    <button onClick={onClick} className={`flex items-center gap-1 px-2 py-1 rounded text-xs font-bold border transition-all ${currentStatus === targetStatus ? colorClass : 'bg-white text-gray-700 shadow-sm border-gray-300'}`} title={label}>
        {icon}<span className={currentStatus === targetStatus ? 'inline' : 'hidden xl:inline'}>{label}</span>
