// Simple SVG Bar Chart Component for Monthly Data
const SimpleBarChart = ({ data, height = 200 }: { data: { label: string, value: number }[], height?: number }) => {
    const maxValue = Math.max(...data.map(d => d.value), 1);

    return (
        <div className="flex items-end justify-between gap-2 h-full w-full" style={{ height }}>
            {data.map((d, i) => {
                const percentage = (d.value / maxValue) * 100;
                return (
                    <div key={i} className="flex-1 flex flex-col items-center group relative h-full justify-end">
                        {/* Tooltip */}
                        <div className="absolute bottom-full mb-2 opacity-0 group-hover:opacity-100 transition-opacity bg-gray-800 text-white text-xs rounded px-2 py-1 pointer-events-none whitespace-nowrap z-10 shadow-lg">
                            {d.label}: {d.value} Einträge
                        </div>
                        <div 
                            className={`w-full max-w-[30px] rounded-t transition-all relative ${d.value === 0 ? 'bg-gray-100' : 'bg-blue-500 hover:bg-blue-600'}`}
                            style={{ height: d.value === 0 ? '4px' : `${percentage}%` }}
                        >
                             {d.value > 0 && <span className="absolute -top-5 left-1/2 -translate-x-1/2 text-[10px] font-bold text-gray-600">{d.value}</span>}
                        </div>
                        <div className="text-[10px] text-gray-500 mt-2 truncate w-full text-center border-t border-gray-200 pt-1">{d.label}</div>
                    </div>
                )
            })}
        </div>
    );
};

export const AnalysisView = () => {
    const { logs, vehicles } = useFleet();
    const safeVehicles = Array.isArray(vehicles) ? vehicles : [];

    // State filters
    const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
    const [selectedType, setSelectedType] = useState<string>('');

    // Prepare Data
    const analysisData = useMemo(() => {
        // 1. Filter Logs (Completed only + Filters)
        const filtered = logs.filter((l: LogEntry) => {
            if (l.status !== 'DONE' || !l.dateCompleted) return false;

            const completionDate = new Date(l.dateCompleted);
            if (completionDate.getFullYear() !== selectedYear) return false;

            const vehicle = safeVehicles.find((v: Vehicle) => v.id === l.vehicleId);
            if (selectedType && vehicle?.type !== selectedType) return false;

            return true;
        });

        // 2. Monthly Stats
        const months = ['Jan', 'Feb', 'Mär', 'Apr', 'Mai', 'Jun', 'Jul', 'Aug', 'Sep', 'Okt', 'Nov', 'Dez'];
        const monthlyData = months.map((m, idx) => ({ label: m, value: 0 }));

        filtered.forEach((l: LogEntry) => {
            if(!l.dateCompleted) return;
            const mIdx = new Date(l.dateCompleted).getMonth(); // 0-11
            if(monthlyData[mIdx]) monthlyData[mIdx].value++;
        });

        // 3. Top Vehicles
        const vehicleCounts: Record<string, number> = {};
        filtered.forEach((l: LogEntry) => {
            if (l.vehicleId) vehicleCounts[l.vehicleId] = (vehicleCounts[l.vehicleId] || 0) + 1;
        });

        const topVehicles = Object.entries(vehicleCounts)
            .map(([vid, count]) => {
                const v = safeVehicles.find((vh: Vehicle) => vh.id === vid);
                return { 
                    id: vid, 
                    count, 
                    license: v?.licensePlate || 'Unbekannt', 
                    model: v ? `${v.manufacturer} ${v.model}` : '',
                    type: v?.type 
                };
            })
            .sort((a, b) => b.count - a.count)
            .slice(0, 10); // Top 10

        // 4. Categories
        const categoryCounts: Record<string, number> = { 'Wartung': 0, 'Reparatur': 0, 'Prüfung': 0 };
        filtered.forEach((l: LogEntry) => {
            if (l.inspectionType) categoryCounts['Prüfung']++;
            else if (l.type === 'Wartung') categoryCounts['Wartung']++;
            else categoryCounts['Reparatur']++;
        });
        const categoryData = Object.entries(categoryCounts).map(([k, v]) => ({ label: k, value: v }));

        return { total: filtered.length, monthlyData, topVehicles, categoryData };

    }, [logs, safeVehicles, selectedYear, selectedType]);

    const availableYears = useMemo(() => {
        const years = new Set<number>();
        years.add(new Date().getFullYear());
        logs.forEach((l: LogEntry) => {
            if(l.dateCompleted) years.add(new Date(l.dateCompleted).getFullYear());
        });
        return Array.from(years).sort((a, b) => b - a);
    }, [logs]);

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-center bg-white p-4 rounded shadow-sm border border-gray-200 gap-4">
                <div className="flex items-center gap-3">
                    <div className="bg-blue-100 p-2 rounded text-blue-600"><Icons.Chart /></div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-800">Auswertung</h2>
                        <div className="text-sm text-gray-500">Erledigte Aufgaben & Prüfungen</div>
                    </div>
                </div>

                <div className="flex gap-2">
                     <select 
                        className="border border-gray-300 rounded px-3 py-2 text-sm font-bold text-gray-700 outline-none focus:border-blue-500 cursor-pointer"
                        value={selectedYear}
                        onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                    >
                        {availableYears.map(y => <option key={y} value={y}>{y}</option>)}
                    </select>

                    <select 
                        className="border border-gray-300 rounded px-3 py-2 text-sm text-gray-700 outline-none focus:border-blue-500 cursor-pointer bg-white"
                        value={selectedType}
                        onChange={(e) => setSelectedType(e.target.value)}
                    >
                        <option value="">Alle Typen</option>
                        {Object.values(VehicleType).map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Main Chart */}
                <div className="lg:col-span-2 bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-6 flex justify-between items-center">
                        <span>Aktivität im Jahresverlauf</span>
                        <span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">Gesamt: <strong>{analysisData.total}</strong></span>
                    </h3>
                    <div className="h-64">
                         <SimpleBarChart data={analysisData.monthlyData} height={250} />
                    </div>
                </div>

                {/* Category Distribution */}
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200 flex flex-col">
                    <h3 className="font-bold text-gray-700 mb-4">Verteilung nach Art</h3>
                    <div className="flex-1 flex flex-col justify-center gap-4">
                        {analysisData.categoryData.map(cat => {
                            const percent = analysisData.total > 0 ? Math.round((cat.value / analysisData.total) * 100) : 0;
                            return (
                                <div key={cat.label}>
                                    <div className="flex justify-between text-sm mb-1">
                                        <span className="font-medium text-gray-600">{cat.label}</span>
                                        <span className="font-bold text-gray-800">{cat.value} ({percent}%)</span>
                                    </div>
                                    <div className="w-full bg-gray-100 rounded-full h-2.5 overflow-hidden">
                                        <div 
                                            className={`h-2.5 rounded-full ${cat.label === 'Wartung' ? 'bg-amber-400' : cat.label === 'Prüfung' ? 'bg-purple-500' : 'bg-blue-500'}`} 
                                            style={{ width: `${percent}%` }}
                                        ></div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Top Vehicles Table */}
            <div className="bg-white rounded shadow-sm border border-gray-200 overflow-hidden">
                <div className="p-4 border-b border-gray-200 bg-gray-50 flex justify-between items-center">
                    <h3 className="font-bold text-gray-700">Fahrzeuge mit höchstem Wartungsaufwand (Top 10)</h3>
                </div>
                <table className="w-full text-left">
                    <thead className="text-xs text-gray-500 uppercase bg-white border-b border-gray-100">
                        <tr>
                            <th className="p-3">Rang</th>
                            <th className="p-3">Kennzeichen</th>
                            <th className="p-3">Fahrzeug</th>
                            <th className="p-3 text-right">Anzahl Einträge</th>
                            <th className="p-3"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100 text-sm">
                        {analysisData.topVehicles.length === 0 ? (
                            <tr><td colSpan={5} className="p-6 text-center text-gray-400 italic">Keine Daten für diesen Zeitraum.</td></tr>
                        ) : (
                            analysisData.topVehicles.map((v, idx) => (
                                <tr key={v.id} className="hover:bg-gray-50">
                                    <td className="p-3 font-mono text-gray-400 font-bold w-12">#{idx + 1}</td>
                                    <td className="p-3 font-bold text-gray-800">{v.license}</td>
                                    <td className="p-3 text-gray-600">{v.model} <span className="text-xs px-1.5 py-0.5 bg-gray-100 rounded ml-2">{v.type}</span></td>
                                    <td className="p-3 text-right font-bold text-blue-600">{v.count}</td>
                                    <td className="p-3 w-full relative"><div className="bg-blue-100 h-1.5 rounded-full" style={{ width: `${Math.min((v.count / (analysisData.topVehicles[0]?.count || 1)) * 100, 100)}%` }}></div></td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { Icons } from '../icons';

interface PdfPreviewProps {
    data: string; // Base64 data URI
    title?: string;
    onClose: () => void;
}

export const PdfPreview = ({ data, title, onClose }: PdfPreviewProps) => {
    const [pdfUrl, setPdfUrl] = useState<string | null>(null);

    useEffect(() => {
        if (!data) return;

        try {
            // 1. Ensure we handle the Data URI correctly
            // Format is usually: "data:application/pdf;base64,JVBERi..."
            let base64Part = data;
            let mimeType = 'application/pdf';

            if (data.includes(',')) {
                const parts = data.split(',');
                base64Part = parts[1];
                const mimeMatch = parts[0].match(/:(.*?);/);
                if (mimeMatch) mimeType = mimeMatch[1];
            }

            // 2. Convert Base64 to Binary
            const binaryString = atob(base64Part);
            const len = binaryString.length;
            const bytes = new Uint8Array(len);
            for (let i = 0; i < len; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }

            // 3. Create Blob and Object URL
            const blob = new Blob([bytes], { type: mimeType });
            const url = URL.createObjectURL(blob);
            setPdfUrl(url);

            // Cleanup when component unmounts or data changes
            return () => {
                URL.revokeObjectURL(url);
            };
        } catch (e) {
            console.error("PDF Conversion Error:", e);
            // Fallback: try raw data string if conversion fails, though likely won't work if blob failed
            setPdfUrl(data);
        }
    }, [data]);

    if (!pdfUrl) return null;

    return (
        <div className="bg-white rounded shadow-lg border border-gray-300 flex flex-col mt-4 animate-fade-in h-[800px]">
            <div className="bg-gray-800 text-white px-4 py-2 flex justify-between items-center rounded-t">
                <span className="font-bold flex items-center gap-2 text-sm md:text-base">
                    <Icons.FileText />
                    {title || 'Dokumentenvorschau'}
                </span>
                <div className="flex gap-2 items-center">
                     <a 
                        href={pdfUrl} 
                        download={`Fahrzeugschein_${title ? title.replace(/\s+/g, '_') : 'Dokument'}.pdf`} 
                        className="text-gray-300 hover:text-white p-1.5 hover:bg-gray-700 rounded transition-colors" 
                        title="Herunterladen"
                     >
                        <Icons.Download />
                    </a>
                    <div className="h-4 w-px bg-gray-600 mx-1"></div>
                    <button 
                        onClick={onClose} 
                        className="text-gray-300 hover:text-white p-1.5 hover:bg-gray-700 rounded transition-colors" 
                        title="Schließen"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                    </button>
                </div>
            </div>
            <div className="flex-1 bg-gray-100 p-0 relative">
                {/* iframe is more reliable than embed for PDF Blobs */}
                <iframe 
                    src={pdfUrl} 
                    className="w-full h-full border-none bg-white"
                    title="PDF Preview"
                />
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { Vehicle, VehicleType } from '../types';
import { Icons } from '../icons';
import { getVehicleTypePriority, parseDateMMYYYY } from '../utils';
import { DateCell } from '../components/Common';
import { useFleet } from '../context/FleetContext';
import { PdfPreview } from '../components/PdfPreview';

export const VehicleListView = ({ onEdit, onAdd }: any) => {
  const { vehicles, deleteVehicle } = useFleet();

  const [sortConfig, setSortConfig] = useState<{ key: string | null, direction: 'asc' | 'desc' }>({ key: null, direction: 'asc' });
  const [filters, setFilters] = useState<{ [key: string]: string }>({});
  const [selectedVehicleForDoc, setSelectedVehicleForDoc] = useState<Vehicle | null>(null);

  const handleSort = (key: keyof Vehicle | 'modelFull') => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
    setSortConfig({ key, direction });
  };

  const handleFilterChange = (key: string, value: string) => setFilters(prev => ({ ...prev, [key]: value }));

  const processedVehicles = useMemo(() => {
    if (!vehicles || !Array.isArray(vehicles)) return [];
    let filtered = [...vehicles];
    Object.keys(filters).forEach(key => {
        const filterVal = filters[key].toLowerCase();
        if(!filterVal) return;
        filtered = filtered.filter(v => {
            let valToCheck = '';
            if (key === 'modelFull') valToCheck = `${v.manufacturer || ''} ${v.model || ''}`;
            // @ts-ignore
            else if (v[key]) valToCheck = String(v[key]);
            return valToCheck.toLowerCase().includes(filterVal);
        });
    });
    if (sortConfig.key) {
        filtered.sort((a, b) => {
            let valA: any = sortConfig.key === 'modelFull' ? `${a.manufacturer || ''} ${a.model || ''}` : a[sortConfig.key as keyof Vehicle];
            let valB: any = sortConfig.key === 'modelFull' ? `${b.manufacturer || ''} ${b.model || ''}` : b[sortConfig.key as keyof Vehicle];
            if (valA === undefined || valA === null) valA = '';
            if (valB === undefined || valB === null) valB = '';
            if (sortConfig.key === 'year') {
                const numA = Number(valA) || 0; const numB = Number(valB) || 0;
                return sortConfig.direction === 'asc' ? (numA - numB) : (numB - numA);
            }
            if (['nextHU', 'nextSP', 'nextUVV', 'nextTacho'].includes(sortConfig.key as string)) {
                const dateA = parseDateMMYYYY(String(valA)); const dateB = parseDateMMYYYY(String(valB));
                return sortConfig.direction === 'asc' ? (dateA - dateB) : (dateB - dateA);
            }
            if (sortConfig.key === 'type') {
                const pA = getVehicleTypePriority(valA); const pB = getVehicleTypePriority(valB);
                return sortConfig.direction === 'asc' ? (pA - pB) : (pB - pA);
            }
            return sortConfig.direction === 'asc' ? String(valA).localeCompare(String(valB)) : String(valB).localeCompare(String(valA));
        });
    }
    return filtered;
  }, [vehicles, sortConfig, filters]);

  const getSortIcon = (colKey: string) => {
     if (sortConfig.key !== colKey) return <span className="text-gray-300"><Icons.SortDefault /></span>;
     return sortConfig.direction === 'asc' ? <span className="text-blue-600"><Icons.SortAsc /></span> : <span className="text-blue-600"><Icons.SortDesc /></span>;
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">Fahrzeuge</h2>
        <div className="flex gap-2">
          <button onClick={onAdd} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded flex items-center gap-2"><Icons.Plus /> Neu</button>
        </div>
      </div>
      <div className="bg-white rounded shadow overflow-x-auto border border-gray-200">
        <table className="w-full text-left border-collapse min-w-[1000px]">
          <thead className="bg-gray-50 text-gray-600 text-sm uppercase tracking-wider">
            <tr className="border-b border-gray-200">
              <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('licensePlate')}><div className="flex items-center gap-2">Kennzeichen {getSortIcon('licensePlate')}</div></th>
              <th className="p-3 cursor-pointer hover:bg-gray-100 select-none" onClick={() => handleSort('type')}><div className="flex items-center gap-2">Typ {getSortIcon('type')}</div></th>
