export const VehicleModal = ({ isOpen, onClose, vehicle, onSave }: any) => {
    const [formData, setFormData] = useState<Partial<Vehicle>>({
        type: VehicleType.PKW,
        licensePlate: '',
        manufacturer: '',
        model: '',
        vin: '',
        year: new Date().getFullYear(),
        notes: '',
        currentMileage: 0,
        registrationDoc: '',
        ...vehicle
    });

    // CRITICAL FIX: Only update form data when Modal OPENS or ID changes. 
    // Do NOT add 'vehicle' to dependency array to prevent overwriting user input on background polling updates.
    useEffect(() => { 
        if (isOpen) {
            setFormData({ 
                type: VehicleType.PKW, 
                registrationDoc: '', 
                ...vehicle 
            }); 
        }
    }, [isOpen, vehicle?.id]);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, registrationDoc: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleRemoveFile = () => {
        if(confirm('Möchten Sie das hinterlegte Dokument wirklich entfernen?')) {
            setFormData(prev => ({ ...prev, registrationDoc: '' }));
