                    <button onClick={handleDownloadBackup} className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded text-sm font-bold w-full flex justify-center items-center gap-2 mt-auto">
                        <Icons.Download /> Backup herunterladen (.db)
                    </button>
                    <p className="mt-2 text-xs text-gray-400">Lädt die aktuelle SQLite Datenbank herunter.</p>
                </div>
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Integrität prüfen</h3>
                    <button onClick={handleIntegrityCheck} disabled={loading} className="bg-slate-700 hover:bg-slate-800 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50">{loading ? 'Prüfe...' : 'Jetzt prüfen'}</button>
                    {checkResult.length > 0 && <div className="mt-4 bg-gray-50 p-2 rounded text-xs font-mono max-h-40 overflow-auto border border-gray-200">{JSON.stringify(checkResult, null, 2)}</div>}
                </div>
                <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Optimierung (VACUUM)</h3>
                     <button onClick={handleVacuum} disabled={loading} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50">{loading ? 'Arbeite...' : 'Optimierung starten'}</button>
                    {message && <div className="mt-4 text-sm text-green-700 font-bold text-center bg-green-50 p-2 rounded border border-green-200">{message}</div>}
                </div>

                 <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                    <h3 className="font-bold text-gray-700 mb-2">Software Update</h3>
                    <button onClick={handleUpdate} disabled={updating} className="bg-slate-600 hover:bg-slate-700 text-white px-4 py-2 rounded text-sm font-bold w-full disabled:opacity-50 flex justify-center items-center gap-2">
                        {updating ? <Icons.Clock /> : <Icons.Download />}
                        {updating ? 'Prüfe auf Updates...' : 'Git Pull ausführen'}
                    </button>
                     {updateResult && (
                        <div className={`mt-4 text-xs font-mono p-2 rounded border max-h-40 overflow-auto ${updateResult.success ? 'bg-green-50 text-green-800 border-green-200' : 'bg-red-50 text-red-800 border-red-200'}`}>
                            <div className="font-bold mb-1">{updateResult.message}</div>
                            {updateResult.details && <div className="opacity-75 whitespace-pre-wrap">{updateResult.details}</div>}
                            {updateResult.success && <div className="mt-2 text-blue-600 font-sans font-bold">Bitte Server/Container neu starten, falls Code geändert wurde.</div>}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

