    nextTacho TEXT, 
    currentMileage INTEGER,
    registrationDoc TEXT
  )`);

  // Migration for existing tables
  db.run("ALTER TABLE vehicles ADD COLUMN registrationDoc TEXT", (err) => {});

  db.run(`CREATE TABLE IF NOT EXISTS logs (
    id TEXT PRIMARY KEY, 
    vehicleId TEXT, 
    type TEXT, 
    description TEXT, 
    priority TEXT, 
    dateAdded TEXT, 
    dateCompleted TEXT, 
    status TEXT, 
    mileage INTEGER, 
    inspectionType TEXT, 
    attachments TEXT,
    FOREIGN KEY(vehicleId) REFERENCES vehicles(id) ON DELETE CASCADE
  )`);

  db.run("ALTER TABLE logs ADD COLUMN attachments TEXT", (err) => {});

  // MIGRATION: Convert all 'Aufgabe' types to 'Reparatur'
  db.run("UPDATE logs SET type = 'Reparatur' WHERE type = 'Aufgabe'", (err) => {
      if(!err) console.log("Migration: Converted 'Aufgabe' to 'Reparatur'");
  });

  db.run(`CREATE TABLE IF NOT EXISTS orders (
    id TEXT PRIMARY KEY, 
    description TEXT, 
    vehicleId TEXT, 
    dateAdded TEXT, 
    status TEXT, 
    supplier TEXT
  )`);
  db.run("ALTER TABLE orders ADD COLUMN supplier TEXT", (err) => {});

  db.run(`CREATE TABLE IF NOT EXISTS repairs (
