// Atomic Task Completion: Updates Log AND Vehicle Mileage in one transaction
app.post('/api/transaction/complete-task', async (req, res) => {
    const { logId, vehicleId, mileage, logData } = req.body;

    db.serialize(() => {
        db.run("BEGIN TRANSACTION");

        const attachmentsJson = JSON.stringify(logData.attachments || []);

        // 1. Update Log
        db.run(`INSERT OR REPLACE INTO logs VALUES (?,?,?,?,?,?,?,?,?,?,?)`, 
            [logId, logData.vehicleId, logData.type, logData.description, logData.priority || 'Normal', logData.dateAdded, logData.dateCompleted, 'DONE', mileage, logData.inspectionType, attachmentsJson], 
            function(err) {
                if (err) {
                    console.error("Trans Error Log:", err);
                    db.run("ROLLBACK");
                    return res.status(500).json({ error: err.message });
                }

                // 2. Check and Update Vehicle Mileage (only if higher)
                db.get("SELECT currentMileage FROM vehicles WHERE id = ?", [vehicleId], (err, row) => {
                    if (err) {
                        db.run("ROLLBACK");
                        return res.status(500).json({ error: err.message });
                    }

                    if (row && mileage > (row.currentMileage || 0)) {
                         db.run("UPDATE vehicles SET currentMileage = ? WHERE id = ?", [mileage, vehicleId], function(err) {
                            if (err) {
                                db.run("ROLLBACK");
                                return res.status(500).json({ error: err.message });
                            }
                            db.run("COMMIT");
                            res.json({ success: true });
                         });
                    } else {
                        // No mileage update needed, just commit
                        db.run("COMMIT");
                        res.json({ success: true });
                    }
                });
            }
        );
    });
});

// NEW: Atomic Inspection Completion (Log + Vehicle Date Update)
app.post('/api/transaction/complete-inspection', async (req, res) => {
    const { logData, nextDate } = req.body;

    // Safety Check: Validate Inspection Type to prevent SQL Injection in column name
    const validTypes = ['HU', 'SP', 'UVV', 'Tacho'];
    if (!logData.inspectionType || !validTypes.includes(logData.inspectionType)) {
        return res.status(400).json({ error: "Invalid inspection type" });
    }

    const colName = `next${logData.inspectionType}`; // Safe due to whitelist check above
    const vehicleId = logData.vehicleId;
    // Format Date: Input YYYY-MM -> MM/YYYY Storage
    const [y, m] = nextDate.split('-');
    const newDateStr = `${m}/${y}`;
    const logId = logData.id || Math.random().toString(36).substr(2, 9);

    db.serialize(() => {
        db.run("BEGIN TRANSACTION");

        // 1. Create Log Entry (Archiving the inspection)
        db.run(`INSERT INTO logs VALUES (?,?,?,?,?,?,?,?,?,?,?)`, 
            [logId, vehicleId, 'Wartung', logData.description, 'Normal', logData.dateAdded, logData.dateCompleted, 'DONE', null, logData.inspectionType, '[]'], 
            function(err) {
                if (err) {
                    db.run("ROLLBACK");
                    return res.status(500).json({ error: "Failed to create log: " + err.message });
                }

                // 2. Update Vehicle Date
                const sql = `UPDATE vehicles SET ${colName} = ? WHERE id = ?`;
                db.run(sql, [newDateStr, vehicleId], function(err) {
                     if (err) {
                        db.run("ROLLBACK");
                        return res.status(500).json({ error: "Failed to update vehicle: " + err.message });
                    }
                    db.run("COMMIT");
                    res.json({ success: true });
                });
            }
        );
    });
});

