import { useState, useEffect, useCallback } from 'react';
import { Vehicle, LogEntry, Order, OrderStatus, Priority } from '../types';
import { api } from '../api';
import { getTodayDate } from '../utils';

export const useFleetData = () => {
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [logs, setLogs] = useState<LogEntry[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const loadData = useCallback(async (silentArg: boolean | any = false) => {
        const isSilent = typeof silentArg === 'boolean' ? silentArg : false;

        if (!isSilent) {
            setLoading(true);
            setError(null);
        }

        try {
            // Robust loading: Use allSettled so if one endpoint fails, others still load
            const results = await Promise.allSettled([
                api.get('/vehicles'),
                api.get('/logs'),
                api.get('/orders')
            ]);

            // Vehicles
            if (results[0].status === 'fulfilled') {
                if(Array.isArray(results[0].value)) setVehicles(results[0].value);
            } else {
                console.error("Failed to load vehicles", results[0].reason);
            }

            // Logs
            if (results[1].status === 'fulfilled') {
                if(Array.isArray(results[1].value)) setLogs(results[1].value);
            } else {
                console.error("Failed to load logs", results[1].reason);
            }

            // Orders
            if (results[2].status === 'fulfilled') {
                if(Array.isArray(results[2].value)) setOrders(results[2].value);
            } else {
                console.error("Failed to load orders", results[2].reason);
            }

            // Check if all failed to set a global error
            if (results.every(r => r.status === 'rejected')) {
                 throw new Error("Verbindung zum Server fehlgeschlagen.");
            }

        } catch (e: any) {
            console.error(e);
            if (!isSilent) {
                setError(e.message || "Fehler beim Laden der Daten");
            }
        } finally {
            if (!isSilent) setLoading(false);
        }
    }, []);

    // Initial Load & Polling
    useEffect(() => { 
        loadData(); 

        const interval = setInterval(() => {
            loadData(true); // Silent update
        }, 30000);

        return () => clearInterval(interval);
    }, [loadData]);

    // --- VEHICLE OPERATIONS ---

    const saveVehicle = async (v: Vehicle) => {
        try {
            if(v.id && vehicles.find(x => x.id === v.id)) {
                await api.put(`/vehicles/${v.id}`, v);
            } else {
                await api.post('/vehicles', v);
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const deleteVehicle = async (id: string) => {
        if(!confirm('Fahrzeug wirklich löschen? Alle zugehörigen Einträge werden ebenfalls gelöscht (Kaskade).')) return false;
        try {
            await api.delete(`/vehicles/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const coupleVehicles = async (motorId: string, trailerId: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        const trailer = vehicles.find(v => v.id === trailerId);
        if(motor && trailer) {
            try {
                await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: trailer.id });
                await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: motor.id });
                await loadData(true);
            } catch(e) { console.error(e); }
        }
    };

    const uncoupleVehicles = async (motorId: string, trailerId?: string) => {
        const motor = vehicles.find(v => v.id === motorId);
        try {
            if(motor) await api.put(`/vehicles/${motor.id}`, { ...motor, coupledVehicleId: null });

            if(trailerId) {
                const trailer = vehicles.find(v => v.id === trailerId);
                if(trailer) await api.put(`/vehicles/${trailer.id}`, { ...trailer, coupledVehicleId: null });
            }
            await loadData(true);
        } catch(e) { console.error(e); }
    };

    // --- LOG / TASK OPERATIONS ---

    const saveLogEntry = async (entries: any[]) => {
        try {
            for (const entry of entries) {
                if(entry.id && logs.find(x => x.id === entry.id)) {
                    await api.put(`/logs/${entry.id}`, entry);
                } else {
                    await api.post('/logs', entry);
                }
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateLogStatus = async (log: LogEntry, newStatus: 'IN_PROGRESS' | 'DONE') => {
        try {
            await api.put(`/logs/${log.id}`, { ...log, status: newStatus });
            await loadData(true);
        } catch (e) { console.error(e); }
    };

    const deleteLog = async (id: string) => {
        if(!confirm('Eintrag löschen?')) return false;
        try {
            await api.delete(`/logs/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    // --- BUSINESS LOGIC: COMPLETIONS (ATOMIC) ---

    // Completes a generic task and updates vehicle mileage via atomic transaction
    const completeTask = async (log: LogEntry, mileage: number) => {
        try {
            const updatedLog = {
                ...log,
                status: 'DONE',
                dateCompleted: getTodayDate(),
                mileage: mileage
            };

            // Use the transaction endpoint to ensure both happen or neither
            await api.post('/transaction/complete-task', {
                logId: log.id,
                vehicleId: log.vehicleId,
                mileage: mileage,
                logData: updatedLog
            });

            await loadData(true);
            return true;
        } catch(e) { 
            console.error("Atomic transaction failed", e); 
            alert("Fehler beim Speichern. Bitte Verbindung prüfen.");
            return false; 
        }
    };

    // Completes an inspection and calculates next date - ATOMICALLY
    const completeInspection = async (log: LogEntry, nextDate: string) => {
        try {
             // Create data for the log archive entry
             const logData = {
                vehicleId: log.vehicleId,
                description: `${log.inspectionType} Prüfung durchgeführt`,
                dateAdded: getTodayDate(),
                dateCompleted: getTodayDate(),
                inspectionType: log.inspectionType
            };

            // Call atomic endpoint
            await api.post('/transaction/complete-inspection', {
                logData,
                nextDate // YYYY-MM from input
            });

            await loadData(true);
            return true;
        } catch(e) { 
            console.error("Inspection completion failed", e); 
            alert("Fehler beim Speichern. Datenkonsistenz gefährdet.");
            return false; 
        }
    };

    // --- ORDER OPERATIONS ---

    const saveOrder = async (ordersList: any[]) => {
        try {
            for (const o of ordersList) {
                if(o.id && orders.find(x => x.id === o.id)) {
                    await api.put(`/orders/${o.id}`, o);
                } else {
                    await api.post('/orders', o);
                }
            }
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    const updateOrderStatus = async (id: string, status: OrderStatus) => {
        const order = orders.find(o => o.id === id);
        if(order) {
            await api.put(`/orders/${id}`, { ...order, status });
            await loadData(true);
        }
    };

    const deleteOrder = async (id: string) => {
        if(!confirm('Bestellung löschen?')) return false;
        try {
            await api.delete(`/orders/${id}`);
            await loadData(true);
            return true;
        } catch (e) { console.error(e); return false; }
    };

    return {
        vehicles, logs, orders, loading, error,
        loadData, saveVehicle, deleteVehicle, coupleVehicles, uncoupleVehicles,
        saveLogEntry, updateLogStatus, deleteLog, completeTask, completeInspection,
        saveOrder, updateOrderStatus, deleteOrder
    };
};

// MockDB for offline fallback
const mockDB = {
    load: (key: string) => {
        try {
            return JSON.parse(localStorage.getItem(`fuhrpark_${key}`) || '[]');
        } catch (e) {
            console.error("MockDB Load Error", e);
            return [];
        }
    },
    save: (key: string, data: any) => {
        try {
            localStorage.setItem(`fuhrpark_${key}`, JSON.stringify(data));
        } catch(e: any) {
            console.error("Storage Error", e);
            if(e.name === 'QuotaExceededError') {
                alert("OFFLINE SPEICHER VOLL! Bitte Bereinigen oder Online gehen.");
            }
        }
    },

    // Helpers to mimic API delays slightly for realism
    async get(collection: string) {
      return this.load(collection);
    },
    async post(collection: string, item: any) {
      const items = this.load(collection);
      const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
      items.push(newItem);
      this.save(collection, items);
      return { success: true, id: newItem.id };
    },
    async put(collection: string, id: string, item: any) {
      const items = this.load(collection);
      const idx = items.findIndex((i:any) => i.id === id);
      if (idx !== -1) {
        items[idx] = item;
        this.save(collection, items);
      }
      return { success: true };
    },
    async delete(collection: string, id: string) {
      const items = this.load(collection);
      const filtered = items.filter((i:any) => i.id !== id);
      this.save(collection, filtered);
      return { success: true };
    },

    // Simulate the server-side atomic transaction for Task Completion
    async transactionCompleteTask(data: any) {
        const { logId, vehicleId, mileage, logData } = data;

        // 1. Update/Insert Log
        const logs = this.load('logs');
        const existingIdx = logs.findIndex((l:any) => l.id === logId);
        if (existingIdx !== -1) logs[existingIdx] = logData;
        else logs.push(logData);
        this.save('logs', logs);

        // 2. Update Vehicle Mileage (if higher)
        const vehicles = this.load('vehicles');
        const vIdx = vehicles.findIndex((v:any) => v.id === vehicleId);
        if (vIdx !== -1) {
            if (mileage > (vehicles[vIdx].currentMileage || 0)) {
                vehicles[vIdx].currentMileage = mileage;
                this.save('vehicles', vehicles);
            }
        }
        return { success: true };
    },

    // Simulate server-side atomic transaction for Inspection Completion
    async transactionCompleteInspection(data: any) {
        const { logData, nextDate } = data;

        // 1. Create Log Archive
        const logs = this.load('logs');
        // Generate a new ID as server would
        const newItem = { ...logData, id: Math.random().toString(36).substr(2, 9), status: 'DONE', priority: 'Normal', type: 'Wartung' };
        logs.push(newItem);
        this.save('logs', logs);

        // 2. Update Vehicle Date
        const vehicles = this.load('vehicles');
        const vIdx = vehicles.findIndex((v:any) => v.id === logData.vehicleId);
        if (vIdx !== -1 && logData.inspectionType) {
             const [y, m] = nextDate.split('-');
             const newDateStr = `${m}/${y}`;
             // Dynamically key access
             const key = `next${logData.inspectionType}`;
             vehicles[vIdx][key] = newDateStr;
             this.save('vehicles', vehicles);
        }
        return { success: true };
    }
  };

  let isOfflineMode = false;

  export const getIsOfflineMode = () => isOfflineMode;

  export const api = {
    // Try server first, fallback to mockDB if fails
    request: async (method: string, endpoint: string, data: any = null) => {
      // Special handling for the transaction endpoints
      if (endpoint === '/transaction/complete-task' && isOfflineMode) return mockDB.transactionCompleteTask(data);
      if (endpoint === '/transaction/complete-inspection' && isOfflineMode) return mockDB.transactionCompleteInspection(data);

      const parts = endpoint.split('/').filter(Boolean);
      const collection = parts[0];
      const id = parts[1];

      if (isOfflineMode) {
         // @ts-ignore
         if (method === 'GET') return mockDB.get(collection);
         // @ts-ignore
         if (method === 'POST') return mockDB.post(collection, data);
         // @ts-ignore
         if (method === 'PUT') return mockDB.put(collection, id, data);
         // @ts-ignore
         if (method === 'DELETE') return mockDB.delete(collection, id);
      }

      try {
        const opts: any = { method, headers: { 'Content-Type': 'application/json' } };
        if (data) opts.body = JSON.stringify(data);

        const res = await fetch(`/api${endpoint}`, opts);
        if (!res.ok) throw new Error('API Error');
        return await res.json();
      } catch (e) {
        if (!isOfflineMode) {
          console.warn('Backend unavailable, switching to Offline Mode (LocalStorage).');
          isOfflineMode = true;
        }
        // Retry with MockDB immediately
        if (endpoint === '/transaction/complete-task') return mockDB.transactionCompleteTask(data);
        if (endpoint === '/transaction/complete-inspection') return mockDB.transactionCompleteInspection(data);
        return api.request(method, endpoint, data);
      }
    },

    get: (url: string) => api.request('GET', url),
    post: (url: string, data: any) => api.request('POST', url, data),
    put: (url: string, data: any) => api.request('PUT', url, data),
    delete: (url: string) => api.request('DELETE', url)
  };

import { Vehicle, Priority, VehicleType, LogEntry } from './types';

export const getTodayDate = () => new Date().toISOString().split('T')[0];
export const isValidDateMMYYYY = (val: string) => /^\d{2}\/\d{4}$/.test(val);

// Convert "MM/YYYY" (Storage) to "YYYY-MM" (Input type="month")
export const toInputFormat = (dateStr?: string) => {
    if (!dateStr) return '';
    const [m, y] = dateStr.split('/');
    if (!m || !y) return '';
    return `${y}-${m}`;
};

// Convert "YYYY-MM" (Input type="month") to "MM/YYYY" (Storage)
export const fromInputFormat = (dateStr: string) => {
    if (!dateStr) return '';
    const [y, m] = dateStr.split('-');
    return `${m}/${y}`;
};

export const parseDateMMYYYY = (dateStr?: string) => {
    if (!dateStr) return 0;
    const parts = dateStr.split('/');
    if (parts.length < 2) return 0;
    const [m, y] = parts;
    if (!m || !y) return 0;
    const date = new Date(parseInt(y), parseInt(m)-1);
    if (isNaN(date.getTime())) return 0; // Robustness Fix
    return date.getTime();
};

export const getVehicleTypePriority = (type: string | any) => {
    switch(type) {
        case VehicleType.LKW: return 1;
        case VehicleType.AUFLIEGER: return 2; // Moved up: LKW then Auflieger
        case VehicleType.TRANSPORTER: return 3;
        case VehicleType.PKW: return 4;
        case VehicleType.ANHAENGER: return 5;
        case VehicleType.MASCHINE: return 6;
        case VehicleType.SONSTIGE: return 7;
        default: return 99;
    }
}

export const getPrioritySortValue = (p: string | Priority) => {
    if (p === Priority.HIGH || (typeof p === 'string' && p.includes('Dringend'))) return 0;
    if (p === Priority.LOW || (typeof p === 'string' && p.includes('Niedrig'))) return 2;
    return 1; // Normal
};

export const getBadgeColor = (type: string) => {
    switch(type) {
        case 'HU': return 'bg-rose-100 text-rose-800 border-rose-200';
        case 'SP': return 'bg-orange-100 text-orange-800 border-orange-200';
        case 'UVV': return 'bg-blue-100 text-blue-800 border-blue-200';
        case 'Tacho': return 'bg-purple-100 text-purple-800 border-purple-200';
        default: return 'bg-gray-100 text-gray-800';
    }
};

export const sortVehicles = (vehicles: Vehicle[]) => {
  return [...vehicles].sort((a, b) => {
    if (a.type !== b.type) {
        return getVehicleTypePriority(a.type) - getVehicleTypePriority(b.type);
    }
    return a.licensePlate.localeCompare(b.licensePlate);
  });
};

export const groupVehiclesByType = (vehicles: Vehicle[]) => {
    const sorted = sortVehicles(vehicles);
    const groups: { [key: string]: Vehicle[] } = {};
    sorted.forEach(v => {
        const typeKey = String(v.type);
        if(!groups[typeKey]) groups[typeKey] = [];
        groups[typeKey].push(v);
    });
    return groups;
}

// Generates virtual log entries for overdue inspections
export const generateVirtualInspections = (vehicles: Vehicle[]): LogEntry[] => {
    const today = new Date();
    const currentMonthStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`; // YYYY-MM

    const virtual: LogEntry[] = [];

    vehicles.forEach((v: Vehicle) => {
        const check = (type: 'HU'|'SP'|'UVV'|'Tacho', dateStr?: string) => {
            if (!dateStr) return;
            // dateStr is MM/YYYY
            const [m, y] = dateStr.split('/');
            if (!m || !y) return;
            const iso = `${y}-${m.padStart(2, '0')}`; // YYYY-MM

            let priority = Priority.NORMAL;
            // If strictly less than current month -> Overdue -> High Priority
            if (iso < currentMonthStr) priority = Priority.HIGH;
            // If equal to current month -> Normal Priority
            else if (iso === currentMonthStr) priority = Priority.NORMAL;
            else return; // Future

            virtual.push({
                id: `virt_${v.id}_${type}_${dateStr}`, // Unique ID
                vehicleId: v.id,
                type: 'Prüfung',
                description: `${type} Fällig (${dateStr})`,
                priority: priority,
                dateAdded: getTodayDate(), 
                status: 'OPEN',
                inspectionType: type,
                isVirtual: true // Flag to handle click differently
            });
        };

        check('HU', v.nextHU);
        check('SP', v.nextSP);
        check('UVV', v.nextUVV);
        check('Tacho', v.nextTacho);
    });

    return virtual;
}
